document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll(".category-pill");n.forEach(function(t){t.addEventListener("click",function(){n.forEach(n=>{n.classList.remove("active","btn-primary"),n.classList.add("btn-outline-secondary")});t.classList.add("active","btn-primary");t.classList.remove("btn-outline-secondary")})})});document.addEventListener("DOMContentLoaded",async function(){const n=document.getElementById("cartBadge");if(n)try{const t=await fetch("/Catalog/GetCartCount");if(!t.ok)throw new Error("HTTP "+t.status);const i=await t.json();n.textContent=i.count>0?i.count:"0"}catch(t){console.error("Не удалось получить количество товаров:",t)}});